def toks(s):return set(re.findall(r'[а-яa-z0-9]+',s.lower().replace('ё','е')))
def canonical(s):return ' '.join(re.findall(r'[а-яa-z0-9]+',s.lower().replace('ё','е')))
for c in cs:
 a=toks(c['question']);nearest=sorted(((len(a & toks(q))/max(1,len(a | toks(q))),s,i,q) for s,i,q in known),reverse=True)[:3]
 c['novelty_check']={'exact_normalized_match':any(canonical(c['question'])==canonical(q) for s,i,q in known),'nearest_by_token_jaccard':[{'similarity':round(sim,3),'set':s,'id':i,'question':q} for sim,s,i,q in nearest],'limitation':'Lexical screen only. Shared constraint/topic families are acknowledged; semantic independence is not established.'}
 assert not c['novelty_check']['exact_normalized_match']
